// Reactive Controller
@RestController
@RequestMapping("/api/users")
public class ReactiveUserController {
    private final ReactiveUserRepository repository;

    public ReactiveUserController(ReactiveUserRepository repository) {
        this.repository = repository;
    }

    @GetMapping
    public Flux<User> getAll() {
        return repository.findAll();
    }

    @GetMapping("/{id}")
    public Mono<User> getById(@PathVariable String id) {
        return repository.findById(id)
            .switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND)));
    }

    @PostMapping
    public Mono<User> create(@Valid @RequestBody User user) {
        return repository.save(user);
    }

    @PutMapping("/{id}")
    public Mono<User> update(@PathVariable String id, @Valid @RequestBody User user) {
        return repository.findById(id)
            .flatMap(existing -> {
                existing.setName(user.getName());
                existing.setEmail(user.getEmail());
                return repository.save(existing);
            })
            .switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND)));
    }

    @DeleteMapping("/{id}")
    public Mono<Void> delete(@PathVariable String id) {
        return repository.deleteById(id);
    }
}

